export function iniciarCenario(config){
const tela=document.querySelector('#cenario'),canvas=document.querySelector('#oceano'),ctx=canvas.getContext('2d'),sprite=new Image();sprite.src='/assets/biblioteca-sprites.webp';let pausado=config.pausado,suspenso=false,qualidade=config.qualidade,anterior=0,tempo=15000,quadro=0,w=1,h=1,dpr=1;let folhas=[],bolhas=[];const recortes={baleia:[28,58,1480,471],tartaruga:[70,552,630,422],folha:[984,527,380,459]};
function quantidade(){const n=qualidade==='economia'?16:qualidade==='cinematografico'?38:26;folhas=Array.from({length:n},(_,i)=>({fase:i/n,x:Math.random(),s:.022+Math.random()*.04,rot:Math.random()*6.28,vel:.75+Math.random()*.6}));bolhas=Array.from({length:n},()=>({x:Math.random(),y:Math.random(),s:.5+Math.random()*1.2,vel:.4+Math.random()*.9}))}
function ajustar(){const area=document.querySelector('.experiencia'),vw=Math.max(1,document.documentElement.clientWidth||innerWidth),vh=Math.max(1,window.visualViewport?.height||innerHeight),altura=Math.max(vh,area.clientHeight||vh),escala=Math.min(vw/1536,altura/1024),larg=1536*escala,alt=1024*escala;tela.style.setProperty('--w',larg+'px');tela.style.setProperty('--h',alt+'px');tela.style.setProperty('--x',Math.max(0,(vw-larg)/2)+'px');tela.style.setProperty('--y',Math.max(0,(altura-alt)/2)+'px');const r=canvas.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,qualidade==='economia'?1:1.5);canvas.width=Math.max(1,Math.round(w*dpr));canvas.height=Math.max(1,Math.round(h*dpr));ctx?.setTransform(dpr,0,0,dpr,0,0);desenhar()}
function desenhar(){if(!ctx||!sprite.complete||!sprite.naturalWidth)return;ctx.clearRect(0,0,w,h);const t=tempo/1000;ctx.save();const b=recortes.baleia;const bx=(1.25-((t/65)%1)*1.7)*w,by=h*(.28+.08*Math.sin(t/13));const bw=w*.68,bh=bw*b[3]/b[2];ctx.globalAlpha=.58;ctx.translate(bx,by);ctx.rotate(-.08+.07*Math.sin(t/4));for(let i=0;i<24;i++){const s=b[2]/24;const desloc=Math.sin(t*1.6-i*.22)*bh*.07*Math.pow(i/24,1.6);ctx.drawImage(sprite,b[0]+i*s,b[1],s,b[3],-bw/2+i*bw/24,desloc,bw/24+.7,bh)}ctx.restore();ctx.save();const a=recortes.tartaruga,ax=(((t/42+.27)%1)*1.5-.25)*w,ay=h*(.61+.03*Math.sin(t/6)),aw=w*.25;ctx.globalAlpha=.6;ctx.translate(ax,ay);ctx.rotate(.07*Math.sin(t/2));ctx.scale(1,1+.035*Math.sin(t*2));ctx.drawImage(sprite,...a,-aw/2,0,aw,aw*a[3]/a[2]);ctx.restore();for(const f of folhas){const u=(t/38*f.vel+f.fase)%1,x=w*(.17+f.x*.58)+Math.sin(u*10+f.rot)*w*.11,y=h*(1.05-u*1.15),s=w*f.s;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(u*10+f.rot)*.55);ctx.scale(.35+.65*Math.abs(Math.sin(u*7+f.rot)),1);ctx.globalAlpha=Math.min(1,u*14,(1-u)*14)*(.5+f.s*5);ctx.drawImage(sprite,...recortes.folha,-s/2,-s*.65,s,s*1.3);ctx.restore()}for(const b of bolhas){const y=(b.y-t*.02*b.vel)%1;ctx.beginPath();ctx.strokeStyle='#b5f3f454';ctx.lineWidth=.65;ctx.arc(b.x*w,((y+1)%1)*h,b.s,0,Math.PI*2);ctx.stroke()}}
function loop(now){quadro=0;if(pausado||suspenso||document.hidden)return;if(now-anterior>32){tempo+=Math.min(now-anterior,45);anterior=now;desenhar()}quadro=requestAnimationFrame(loop)}function retomar(){if(!quadro&&!pausado&&!suspenso&&!document.hidden){anterior=performance.now();quadro=requestAnimationFrame(loop)}}function parar(){cancelAnimationFrame(quadro);quadro=0}
sprite.onload=()=>{desenhar();retomar()};quantidade();ajustar();new ResizeObserver(ajustar).observe(document.querySelector('.experiencia'));addEventListener('resize',ajustar,{passive:true});document.addEventListener('visibilitychange',()=>document.hidden?parar():retomar());addEventListener('pointermove',e=>{if(innerWidth<=900||pausado||suspenso||e.pointerType==='touch')return;tela.style.setProperty('--mx',((e.clientX/innerWidth-.5)*-9)+'px');tela.style.setProperty('--my',((e.clientY/innerHeight-.5)*-5)+'px')},{passive:true});return{pausar(v){pausado=v;v?parar():retomar()},suspender(v){suspenso=v;v?parar():retomar()},qualidade(v){qualidade=v;quantidade();ajustar()}}}
